// Package contract implements the opt-in query contract checking flow.
//
// A contract snapshot captures the stable, public surface of the query layer
// generated by sqlc for a single SQL package: query names, query commands,
// parameters and result columns together with their types. Snapshots are
// compared on subsequent runs to surface new, backwards-compatible and
// breaking changes before callers of the generated code are affected.
package contract

import (
	"bytes"
	"encoding/json"
	"sort"

	"github.com/sqlc-dev/sqlc/internal/compiler"
)

// SnapshotVersion is the version of the on-disk snapshot format.
const SnapshotVersion = 1

// Snapshot is the contract of one SQL package.
type Snapshot struct {
	// Version is the snapshot format version.
	Version int `json:"version"`
	// Package is the configured name of the SQL package.
	Package string `json:"package"`
	// Engine is the SQL engine used to parse the package.
	Engine string `json:"engine"`
	// Queries are the contract entries, sorted by name.
	Queries []QueryContract `json:"queries"`
}

// QueryContract is the contract of a single named query.
type QueryContract struct {
	// Name is the query name as declared in the query annotation.
	Name string `json:"name"`
	// Cmd is the query command, e.g. ":one", ":many", ":exec".
	Cmd string `json:"cmd"`
	// Params are the query parameters, sorted by number.
	Params []ParamContract `json:"params"`
	// Columns are the result columns, in result order.
	Columns []FieldContract `json:"columns"`
}

// ParamContract is a single query parameter.
type ParamContract struct {
	Number int           `json:"number"`
	Field  FieldContract `json:"field"`
}

// FieldContract describes a typed field shared by parameters and columns.
type FieldContract struct {
	// Name is the field name. For parameters it is the parameter (or column)
	// name used in the generated params struct.
	Name string `json:"name"`
	// Type is the fully qualified type name.
	Type string `json:"type"`
	// NotNull reports whether the field is non-nullable.
	NotNull bool `json:"not_null"`
	// Unsigned reports whether the numeric type is unsigned.
	Unsigned bool `json:"unsigned"`
	// IsArray reports whether the field is an array type.
	IsArray bool `json:"is_array"`
	// ArrayDims is the number of array dimensions.
	ArrayDims int `json:"array_dims,omitempty"`
}

// typeName renders a stable, fully qualified name for a column type. It
// mirrors the identifier built for the codegen plugin request.
func typeName(c *compiler.Column) string {
	if c.Type != nil {
		switch {
		case c.Type.Catalog != "" && c.Type.Schema != "":
			return c.Type.Catalog + "." + c.Type.Schema + "." + c.Type.Name
		case c.Type.Schema != "":
			return c.Type.Schema + "." + c.Type.Name
		case c.Type.Name != "":
			return c.Type.Name
		}
	}
	return c.DataType
}

func fieldFromColumn(c *compiler.Column) FieldContract {
	if c == nil {
		return FieldContract{}
	}
	return FieldContract{
		Name:      c.Name,
		Type:      typeName(c),
		NotNull:   c.NotNull,
		Unsigned:  c.Unsigned,
		IsArray:   c.IsArray,
		ArrayDims: c.ArrayDims,
	}
}

// Build creates a normalized snapshot from a compiler result. Queries are
// sorted by name and parameters by number so that moving queries between
// files or reordering parameters in the source does not perturb the
// snapshot. Result columns keep their positional order.
func Build(packageName, engine string, result *compiler.Result) *Snapshot {
	snap := &Snapshot{
		Version: SnapshotVersion,
		Package: packageName,
		Engine:  engine,
		Queries: make([]QueryContract, 0, len(result.Queries)),
	}
	for _, q := range result.Queries {
		if q == nil {
			continue
		}
		qc := QueryContract{
			Name:    q.Metadata.Name,
			Cmd:     q.Metadata.Cmd,
			Params:  make([]ParamContract, 0, len(q.Params)),
			Columns: make([]FieldContract, 0, len(q.Columns)),
		}
		for _, p := range q.Params {
			qc.Params = append(qc.Params, ParamContract{
				Number: p.Number,
				Field:  fieldFromColumn(p.Column),
			})
		}
		for _, c := range q.Columns {
			qc.Columns = append(qc.Columns, fieldFromColumn(c))
		}
		sort.Slice(qc.Params, func(i, j int) bool {
			return qc.Params[i].Number < qc.Params[j].Number
		})
		snap.Queries = append(snap.Queries, qc)
	}
	sort.Slice(snap.Queries, func(i, j int) bool {
		return snap.Queries[i].Name < snap.Queries[j].Name
	})
	return snap
}

// Marshal serializes the snapshot to stable, indented JSON with a trailing
// newline. The output is deterministic for equal snapshots.
func (s *Snapshot) Marshal() ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetIndent("", "  ")
	enc.SetEscapeHTML(false)
	if err := enc.Encode(s); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// Unmarshal parses a snapshot, rejecting unknown fields so that snapshots
// from newer or incompatible tools are detected instead of silently losing
// information.
func Unmarshal(blob []byte) (*Snapshot, error) {
	dec := json.NewDecoder(bytes.NewReader(blob))
	dec.DisallowUnknownFields()
	var snap Snapshot
	if err := dec.Decode(&snap); err != nil {
		return nil, err
	}
	return &snap, nil
}
